  alphaDTC_gen: FOR ii IN 0 TO 44 GENERATE
    
    alphaDTC(ii) <= "011111111" WHEN (alpha_signed(ii)(10) = '0') AND (alpha_signed(ii)(9 DOWNTO 8) /= "00") ELSE
        "100000000" WHEN (alpha_signed(ii)(10) = '1') AND (alpha_signed(ii)(9 DOWNTO 8) /= "11") ELSE
        alpha_signed(ii)(8 DOWNTO 0);
  END GENERATE alphaDTC_gen;


