      '0' WHEN resize(addressGeneration_rdAddr, 6) = addressGeneration_add_temp ELSE
      addressGeneration_rdValid;
  
  addressGeneration_wrAddr_temp <= to_unsigned(16#00#, 5) WHEN reset_1 /= '0' ELSE
